import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph-CSI- The Engine Behind Persistent Storage in Kubernetes - Niels de Vos & Madhu Rajanna","description":"","frontmatter":{"title":"Ceph-CSI- The Engine Behind Persistent Storage in Kubernetes - Niels de Vos & Madhu Rajanna","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Kubernetes","CSI","Storage","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph-CSI_-_The_Engine_Behind_Persistent_Storage_in_Kubernetes_-_Niels_de_Vos_Madhu_Rajanna.md","filePath":"posts/2025/Ceph-CSI_-_The_Engine_Behind_Persistent_Storage_in_Kubernetes_-_Niels_de_Vos_Madhu_Rajanna.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Ceph-CSI_-_The_Engine_Behind_Persistent_Storage_in_Kubernetes_-_Niels_de_Vos_Madhu_Rajanna.md"};function r(l,e,s,h,_,d){return i(),t("div",null,[...e[0]||(e[0]=[n('<p>Ceph-CSI项目是Kubernetes持久存储的重要驱动力量，本次会议由IBM的Niels de Vos和Madhu Rajanna主持，深入探讨了Ceph CSI及其生态系统组件的技术。</p><h3 id="会议核心内容" tabindex="-1">会议核心内容 <a class="header-anchor" href="#会议核心内容" aria-label="Permalink to &quot;会议核心内容&quot;">​</a></h3><h4 id="_1-ceph-csi基础架构" tabindex="-1">1. Ceph CSI基础架构 <a class="header-anchor" href="#_1-ceph-csi基础架构" aria-label="Permalink to &quot;1. Ceph CSI基础架构&quot;">​</a></h4><ul><li><strong>CSI规范</strong>：定义了容器存储接口标准，提供基础存储操作，如volume创建/删除和snapshotting等。</li><li><strong>Kubernetes集成</strong>：通过PV与CSI volume的映射，用户通过PVC申请存储资源。</li></ul><h4 id="_2-ceph-csi支持的后端存储" tabindex="-1">2. Ceph CSI支持的后端存储 <a class="header-anchor" href="#_2-ceph-csi支持的后端存储" aria-label="Permalink to &quot;2. Ceph CSI支持的后端存储&quot;">​</a></h4><ul><li><strong>CephFS</strong>：多节点共享文件系统，支持读写多（RWX）。</li><li><strong>RBD</strong>：块存储，支持虚拟机live migration，支持读写一次（RWO）。</li><li><strong>NFS</strong>：网络文件系统，兼容传统NFS场景。</li></ul><h4 id="_3-关键功能特性" tabindex="-1">3. 关键功能特性 <a class="header-anchor" href="#_3-关键功能特性" aria-label="Permalink to &quot;3. 关键功能特性&quot;">​</a></h4><ul><li><strong>标准CSI功能</strong>：volume创建/删除、容量扩展、快照管理、volume group snapshot、RBD Changed Block Tracking。</li><li><strong>非标准扩展功能</strong>：topology-based provisioning、静态数据加密、CSI add-ons的实验性功能。</li></ul><h4 id="_4-ceph-csi-operator" tabindex="-1">4. Ceph CSI Operator <a class="header-anchor" href="#_4-ceph-csi-operator" aria-label="Permalink to &quot;4. Ceph CSI Operator&quot;">​</a></h4><ul><li><strong>设计目标</strong>：统一部署方式，减少维护负担，保持配置简洁性。</li><li><strong>CRD设计</strong>：OperatorConfig、Driver、CephConnection、ClientProfile。</li></ul><h4 id="_5-csi-add-ons项目" tabindex="-1">5. CSI Add-ons项目 <a class="header-anchor" href="#_5-csi-add-ons项目" aria-label="Permalink to &quot;5. CSI Add-ons项目&quot;">​</a></h4><ul><li><strong>设计理念</strong>：扩展CSI规范外的存储功能，提供通用框架供其他存储供应商使用。</li><li><strong>核心功能</strong>：密钥轮换、网络隔离、空间回收、卷复制、卷状态报告。</li></ul><h4 id="未来路线图" tabindex="-1">未来路线图 <a class="header-anchor" href="#未来路线图" aria-label="Permalink to &quot;未来路线图&quot;">​</a></h4><ul><li>NVMe-oF支持</li><li>Operator增强</li><li>存储功能扩展</li></ul><h4 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h4><ul><li>用户迁移</li><li>功能推广</li><li>社区协作</li></ul><h4 id="q-a重点" tabindex="-1">Q&amp;A重点 <a class="header-anchor" href="#q-a重点" aria-label="Permalink to &quot;Q&amp;A重点&quot;">​</a></h4><ul><li>网络隔离在跨集群场景的应用价值</li><li>密钥轮换的安全实践</li><li>Volume Group复制的一致性保障</li><li>与Kubernetes原生功能的集成深度</li></ul><p>本次会议全面展示了Ceph CSI生态系统的最新进展，特别是在操作简化和功能扩展方面的创新，为Kubernetes上的Ceph存储管理提供了企业级解决方案。</p>',19)])])}const C=a(o,[["render",r]]);export{p as __pageData,C as default};
